#!/bin/bash\n\n# smg4OS Setup Assistant - FEATURING: SMG4 HIMSELF!\n# \"Hey, it's me, SMG4! Let me help you set up this glitchy... I MEAN, AWESOME distro!\"\n\nset -e\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nPROJECT_ROOT=\"$(dirname \"$SCRIPT_DIR\")\"\nWIZARD_DIR=\"$PROJECT_ROOT/setup-wizard\"\nCONFIG_DIR=\"$WIZARD_DIR/config\"\n\n# Colors\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nMAGENTA='\\033[0;35m'\nCYAN='\\033[0;36m'\nWHITE='\\033[1;37m'\nGOLD='\\033[38;5;220m'\nNC='\\033[0m'\n\n# SMG4 Personality Functions\nsmg4_intro() {\n    clear\n    cat << 'EOF'\n\n    ╔════════════════════════════════════════════════════════════════╗\n    ║                                                                ║\n    ║              🎮 WELCOME TO smg4OS! 🎮                         ║\n    ║                                                                ║\n    ║   Hey there! It's me, SMG4! You know, that guy who makes      ║\n    ║   glitchy Mario videos? Well, I'm here to help you set up     ║\n    ║   your new smg4OS installation! Let's make this LEGENDARY!    ║\n    ║                                                                ║\n    ║          *guitar riff plays in the background*                ║\n    ║                                                                ║\n    ╚════════════════════════════════════════════════════════════════╝\n\nEOF\n    sleep 2\n}\n\nsmg4_say() {\n    local message=\"$1\"\n    echo -e \"${GOLD}[SMG4]${NC} ${CYAN}$message${NC}\"\n}\n\nsmg4_warning() {\n    local message=\"$1\"\n    echo -e \"${RED}[SMG4]${NC} ${YELLOW}⚠️  WARNING: $message${NC}\"\n}\n\nsmg4_success() {\n    local message=\"$1\"\n    echo -e \"${GREEN}[SMG4]${NC} ✓ $message${NC}\"\n}\n\nsmg4_joke() {\n    local jokes=(\n        \"Why did the Linux user sit on the toilet? Because they wanted to do a kernel dump!\"\n        \"I could make a joke about UDP, but you might not get it...\"\n        \"How many programmers does it take to change a light bulb? None, that's a hardware problem!\"\n        \"Why do Java developers wear glasses? Because they can't C#!\"\n        \"A SQL query walks into a bar, walks up to two tables and asks... 'Can I join you?'\"\n        \"Why did the developer go broke? Because he used up all his cache!\"\n    )\n    local index=$((RANDOM % ${#jokes[@]}})\n    echo -e \"${MAGENTA}[SMG4's Dumb Joke]${NC} ${jokes[$index]}\"\n}\n\n# Main Setup Flow\nsmg4_intro\n\necho \"\"\nsmg4_say \"Alright, let me show you what we're setting up here!\"\nsleep 1\n\necho \"\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho -e \"${BLUE}  SETUP OPTIONS${NC}\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho \"\"\necho \"What do you want to do?\"\necho \"\"\necho -e \"${CYAN}1)${NC} ${WHITE}Full System Setup${NC}       (Recommended - does everything)\"\necho -e \"${CYAN}2)${NC} ${WHITE}Desktop Theming${NC}        (Just set up the pretty stuff)\"\necho -e \"${CYAN}3)${NC} ${WHITE}Boot Customization${NC}    (Make the boot screen awesome)\"\necho -e \"${CYAN}4)${NC} ${WHITE}Development Setup${NC}     (For developers who actually code)\"\necho -e \"${CYAN}5)${NC} ${WHITE}Quick Setup${NC}           (Fast setup for the impatient)\"\necho -e \"${CYAN}6)${NC} ${WHITE}View System Info${NC}      (Show me what we're working with)\"\necho -e \"${CYAN}0)${NC} ${WHITE}Exit${NC}                  (Coward mode activated)\"\necho \"\"\n\nread -p \"Enter your choice [0-6]: \" choice\n\necho \"\"\ncase $choice in\n    1)\n        smg4_say \"Alright, let's do this! Full system setup incoming!\"\n        sleep 1\n        \"$WIZARD_DIR/scripts/full-setup.sh\"\n        ;;\n    2)\n        smg4_say \"Ohhh, I see you care about how things look! Me too!\"\n        sleep 1\n        \"$WIZARD_DIR/scripts/theme-setup.sh\"\n        ;;\n    3)\n        smg4_say \"Gonna make that boot screen *chef's kiss*!\"\n        sleep 1\n        \"$WIZARD_DIR/scripts/boot-setup.sh\"\n        ;;\n    4)\n        smg4_say \"A developer! Finally, someone who actually knows what they're doing!\"\n        sleep 1\n        \"$WIZARD_DIR/scripts/dev-setup.sh\"\n        ;;\n    5)\n        smg4_say \"In a hurry? I respect that. Let's speed run this!\"\n        sleep 1\n        \"$WIZARD_DIR/scripts/quick-setup.sh\"\n        ;;\n    6)\n        smg4_say \"Let me take a look at your system...\"\n        \"$WIZARD_DIR/scripts/system-info.sh\"\n        ;;\n    0)\n        smg4_say \"See you later! Don't forget to set up smg4OS properly!\"\n        exit 0\n        ;;\n    *)\n        smg4_warning \"That's not a valid option! Try again, genius.\"\n        exec \"$0\"\n        ;;\nesac\n\necho \"\"\nsmg4_success \"Setup complete! Your system is now SMG4-approved! 🎮\"\necho \"\"\nsmg4_say \"Thanks for using smg4OS! Remember: this distro is powered by memes and chaos.\"\nsmg4_say \"If anything breaks, blame Mario. If everything works, YOU'RE WELCOME!\"\necho \"\"\nsmg4_joke\necho \"\"\n"